<?php
namespace GuidTool;
final class Store {
    private $dir;
    public function __construct($root){$this->dir=dirname(rtrim($root,'/')).'/.bitrix-guid-tool-private-'.substr(hash('sha256',realpath($root)?:$root),0,12);if(!is_dir($this->dir)&&!mkdir($this->dir,0700,true)&&!is_dir($this->dir))throw new \RuntimeException('Не удалось создать хранилище');@chmod($this->dir,0700);file_put_contents($this->dir.'/.htaccess',"Deny from all\nRequire all denied\n");file_put_contents($this->dir.'/index.php','<?php http_response_code(403);');}
    private function path($profile){return $this->dir.'/'.hash('sha256',$profile).'.json';}
    public function load($profile){$p=$this->path($profile);if(!is_file($p))return []; $s=json_decode(file_get_contents($p),true);if(!is_array($s))throw new \RuntimeException('Хранилище повреждено');return $s;}
    public function save($profile,$s){$p=$this->path($profile);$tmp=tempnam($this->dir,'job-');if(!$tmp)throw new \RuntimeException('Нет места для состояния');$json=json_encode($s,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if(file_put_contents($tmp,$json,LOCK_EX)!==strlen($json)){@unlink($tmp);throw new \RuntimeException('Не удалось сохранить состояние');}@chmod($tmp,0600);if(!rename($tmp,$p))throw new \RuntimeException('Не удалось зафиксировать состояние');}
    public function lock($profile){$f=fopen($this->dir.'/'.hash('sha256',$profile).'.lock','c');if(!$f||!flock($f,LOCK_EX|LOCK_NB))throw new \RuntimeException('Для этого сайта уже выполняется операция');return $f;}
    private function archiveDir($profile){$d=$this->dir.'/archive-'.hash('sha256',$profile);if(!is_dir($d)&&!mkdir($d,0700,true)&&!is_dir($d))throw new \RuntimeException('Не удалось создать архив');return $d;}
    public function archiveSave($profile,$job,$xlsxPath){$id=(string)($job['archive_id']??'');if(!preg_match('/^[a-f0-9]{32}$/',$id))throw new \RuntimeException('Неверный ID архива');$d=$this->archiveDir($profile);$file=$d.'/'.$id.'.xlsx';$tmp=tempnam($d,'report-');if(!$tmp||!copy($xlsxPath,$tmp)||!rename($tmp,$file))throw new \RuntimeException('Не удалось сохранить архивный XLSX');@chmod($file,0600);$meta=['id'=>$id,'created'=>$job['created']??'','started'=>$job['started']??'','completed'=>$job['completed']??'','profile'=>$profile,'admin'=>$job['admin']??0,'phase'=>$job['phase']??'','stats'=>\GuidTool\CoreStats::count($job)];$mtmp=tempnam($d,'meta-');if(!$mtmp||file_put_contents($mtmp,json_encode($meta,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR))===false||!rename($mtmp,$d.'/'.$id.'.json'))throw new \RuntimeException('Не удалось сохранить метаданные архива');@chmod($d.'/'.$id.'.json',0600);}
    public function archiveList($profile){$d=$this->archiveDir($profile);$out=[];foreach(glob($d.'/*.json')?:[] as $p){$m=json_decode(file_get_contents($p),true);if(is_array($m)&&preg_match('/^[a-f0-9]{32}$/',$m['id']??'')&&is_file($d.'/'.$m['id'].'.xlsx'))$out[]=$m;}usort($out,function($a,$b){return strcmp($b['started']??$b['created'],$a['started']??$a['created']);});return $out;}
    public function archivePath($profile,$id){if(!preg_match('/^[a-f0-9]{32}$/D',(string)$id))throw new \RuntimeException('Неверный ID отчёта');$p=$this->archiveDir($profile).'/'.$id.'.xlsx';if(!is_file($p))throw new \RuntimeException('Отчёт не найден');return $p;}
    public function archiveDelete($profile,$ids){$d=$this->archiveDir($profile);foreach($ids as $id){if(!preg_match('/^[a-f0-9]{32}$/D',(string)$id))throw new \RuntimeException('Неверный ID отчёта');foreach(['xlsx','json'] as $ext){$p=$d.'/'.$id.'.'.$ext;if(is_file($p)&&!unlink($p))throw new \RuntimeException('Не удалось удалить отчёт');}}}
    private function duplicatesPath($profile){return $this->dir.'/'.hash('sha256',$profile).'-duplicates.xlsx';}
    public function duplicatesSave($profile,$source){$dest=$this->duplicatesPath($profile);$tmp=tempnam($this->dir,'dups-');if(!$tmp||!copy($source,$tmp)||!rename($tmp,$dest))throw new \RuntimeException('Не удалось сохранить XLSX дублей');@chmod($dest,0600);}
    public function duplicatesFile($profile){$path=$this->duplicatesPath($profile);if(!is_file($path))throw new \RuntimeException('Сначала примените подготовку');return $path;}
    public function duplicatesClear($profile){$path=$this->duplicatesPath($profile);if(is_file($path))@unlink($path);}
    public function unlock($f){flock($f,LOCK_UN);fclose($f);}
}
